// Streambuf holds data read in blocks from OS (canonical mode)

// Input: "42\nHello World\n"
int val;
std::string s1, s2;

std::cin >> val;      // Extracts 42. Buffer remains: "\nHello World\n"

// Problem: Trailing newline causes subsequent getline to read empty line
// std::getline(std::cin, s1); // s1 = ""

// Required fix: Discard the residual newline character
std::cin.ignore(256, '\n');

std::getline(std::cin, s1); // Extracts "Hello World"
                            // Consumes and discards trailing '\n'

// Explicitly reading a different delimiter (e.g., comma)
std::getline(std::cin, s2, ','); // Reads until ',', ',' is discarded.
